func (q *Queries) UpsertCommissionSetting(ctx context.Context, arg UpsertCommissionSettingParams) (CommissionSetting, error) {
	row := q.db.QueryRowContext(ctx, upsertCommissionSetting,
		arg.OrganizationID,
		arg.TargetCustomerID,
		arg.Type,
		arg.Value,
		arg.Conditions,
		arg.IsActive,
	)
	var i CommissionSetting
	err := row.Scan(
		&i.ID,
		&i.OrganizationID,
		&i.TargetCustomerID,
		&i.Type,
		&i.Value,
		&i.Conditions,
		&i.IsActive,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
	)
	return i, err
}
